create table app_users (active boolean not null, id uuid not null, branch_code varchar(255), email varchar(255) not null unique, name varchar(255) not null, organization varchar(255) not null, password_hash varchar(255) not null, role varchar(255) not null, primary key (id));
create table approval_policies (auto_approve_max_litres numeric(38,2) not null, enforce_credit_limit boolean not null, id uuid not null, organization varchar(255) not null unique, primary key (id));
create table audit_logs (status integer not null, at timestamp(6) with time zone not null, id uuid not null, path varchar(500) not null, actor_email varchar(255), actor_role varchar(255), ip varchar(255), method varchar(255) not null, organization varchar(255), primary key (id));
create table branches (id uuid not null, city varchar(255), code varchar(255) not null, name varchar(255) not null, organization varchar(255) not null, primary key (id), unique (organization, code));
create table cctv_events (confidence float(53) not null, at timestamp(6) with time zone not null, id uuid not null, risk_event_id uuid, camera_id varchar(255) not null, clip_ref varchar(255), kind varchar(255) not null, plate varchar(255), site_code varchar(255) not null, primary key (id));
create table credit_accounts (credit_limit numeric(38,2) not null, monthly_budget numeric(38,2) not null, id uuid not null, organization varchar(255) not null unique, terms varchar(255) not null, primary key (id));
create table delivery_notes (delivered_litres numeric(38,2), dest_lat float(53), dest_lng float(53), loaded_litres numeric(38,2), planned_litres numeric(38,2) not null, surcharge_per_litre numeric(38,2) not null, created_at timestamp(6) with time zone not null, id uuid not null, customer varchar(255), destination_name varchar(255) not null, destination_site_code varchar(255), destination_type varchar(255) not null, driver_name varchar(255) not null, number varchar(255) not null unique, origin_site_code varchar(255) not null, product varchar(255) not null, seal_numbers varchar(255), status varchar(255) not null, truck_reg varchar(255) not null, primary key (id));
create table device_status (online boolean not null, last_seen timestamp(6) with time zone not null, id uuid not null, device_id varchar(255) not null unique, kind varchar(255) not null, site_code varchar(255) not null, primary key (id));
create table drivers (active boolean not null, id uuid not null, license_no varchar(255), name varchar(255) not null, organization varchar(255) not null, phone varchar(255), pin_hash varchar(255), vehicle_reg varchar(255), primary key (id), unique (organization, name));
create table evidence_records (created_at timestamp(6) with time zone not null, id uuid not null, risk_event_id uuid not null, content_hash varchar(255) not null, prev_hash varchar(255) not null, content oid not null, primary key (id));
create table fraud_cases (closed_at timestamp(6) with time zone, opened_at timestamp(6) with time zone not null, id uuid not null, risk_event_id uuid not null unique, notes varchar(2000), assigned_to varchar(255), outcome varchar(255), status varchar(255) not null, primary key (id));
create table fuel_orders (quantity_litres numeric(38,2) not null, unit_price_snapshot numeric(38,2) not null, created_at timestamp(6) with time zone not null, id uuid not null, bulk_ref varchar(255), cost_centre varchar(255), customer_name varchar(255) not null, destination varchar(255), driver_name varchar(255) not null, fuel_product varchar(255) not null, initiated_by varchar(255) not null, number varchar(255) not null unique, price_source varchar(255), rejection_reason varchar(255), site_code varchar(255), site_name varchar(255) not null, status varchar(255) not null check ((status in ('DRAFT','PENDING_CUSTOMER_APPROVAL','PENDING_APPROVAL','APPROVED','AUTHORIZED','FULFILLED','REJECTED','CANCELLED','EXPIRED'))), vehicle_reg varchar(255) not null, primary key (id));
create table fuel_transactions (amount numeric(38,2) not null, unit_price numeric(38,2) not null, volume_litres numeric(38,2) not null, dispensed_at timestamp(6) with time zone not null, authorization_id uuid not null, id uuid not null, order_id uuid not null, attendant_name varchar(255) not null, driver_name varchar(255) not null, site_name varchar(255) not null, vehicle_reg varchar(255) not null, primary key (id));
create table fx_rates (rate numeric(18,6) not null, at timestamp(6) with time zone not null, id uuid not null, from_currency varchar(255) not null, to_currency varchar(255) not null, primary key (id), unique (from_currency, to_currency));
create table gps_positions (lat float(53) not null, lng float(53) not null, speed_kph float(53), at timestamp(6) with time zone not null, delivery_id uuid not null, id uuid not null, primary key (id));
create table invoice_lines (amount numeric(38,2) not null, litres numeric(38,2) not null, unit_price numeric(38,2) not null, id uuid not null, invoice_id uuid not null, transaction_id uuid not null unique, description varchar(255), order_number varchar(255), primary key (id));
create table invoices (due_date date not null, issue_date date not null, paid numeric(38,2) not null, subtotal numeric(38,2) not null, tax numeric(38,2) not null, tax_rate_percent numeric(38,2) not null, total numeric(38,2) not null, created_at timestamp(6) with time zone not null, id uuid not null, currency varchar(255) not null, fiscal_ref varchar(255), number varchar(255) not null unique, organization varchar(255) not null, tax_name varchar(255) not null, primary key (id));
create table ledger_entries (credit numeric(38,2) not null, debit numeric(38,2) not null, at timestamp(6) with time zone not null, id uuid not null, ref_id uuid, memo varchar(300), account varchar(255) not null, organization varchar(255) not null, ref_type varchar(255), primary key (id));
create table list_prices (unit_price numeric(38,2) not null, valid_from date not null, id uuid not null, currency varchar(255) not null, product varchar(255) not null unique, primary key (id));
create table notifications (created_at timestamp(6) with time zone not null, id uuid not null, message varchar(600) not null, channel varchar(255) not null, kind varchar(255) not null, organization varchar(255) not null, phone varchar(255), recipient_name varchar(255), reference varchar(255), status varchar(255) not null, primary key (id));
create table order_status_history (at timestamp(6) with time zone not null, id uuid not null, order_id uuid not null, reason varchar(500), actor varchar(255) not null, from_status varchar(255), to_status varchar(255) not null, primary key (id));
create table organizations (created_at timestamp(6) with time zone not null, id uuid not null, brand_name varchar(255), contact_email varchar(255), contact_phone varchar(255), country varchar(255), currency varchar(255), name varchar(255) not null unique, primary_color varchar(255), registration_no varchar(255), status varchar(255) not null, type varchar(255) not null, primary key (id));
create table otp_attempts (at timestamp(6) with time zone not null, authorization_id uuid, id uuid not null, order_id uuid, detail varchar(400), attendant varchar(255) not null, outcome varchar(255) not null, primary key (id));
create table otp_authorizations (max_volume_litres numeric(38,2) not null, expires_at timestamp(6) with time zone not null, redeemed_at timestamp(6) with time zone, version bigint not null, id uuid not null, order_id uuid not null, code_hash varchar(255) not null unique, driver_name varchar(255) not null, fuel_product varchar(255) not null, site_name varchar(255) not null, status varchar(255) not null check ((status in ('ACTIVE','REDEEMED','EXPIRED','REVOKED'))), vehicle_reg varchar(255) not null, primary key (id));
create table outbound_events (at timestamp(6) with time zone not null, id uuid not null, detail varchar(300), kind varchar(255) not null, reference varchar(255) not null, status varchar(255) not null, target varchar(255) not null, primary key (id));
create table payments (amount numeric(38,2) not null, received_at timestamp(6) with time zone not null, id uuid not null, invoice_id uuid not null, method varchar(255) not null, organization varchar(255) not null, reference varchar(255), primary key (id));
create table price_history (effective_date date not null, new_price numeric(38,2) not null, previous_price numeric(38,2), at timestamp(6) with time zone not null, id uuid not null, rule_id uuid not null, approved_by varchar(255) not null, organization varchar(255) not null, product varchar(255) not null, proposed_by varchar(255) not null, site_code varchar(255), primary key (id));
create table price_rules (min_litres numeric(38,2) not null, rule_value numeric(38,2) not null, valid_from date not null, valid_to date, proposed_at timestamp(6) with time zone not null, id uuid not null, decided_by varchar(255), mode varchar(255) not null, organization varchar(255) not null, product varchar(255) not null, proposed_by varchar(255) not null, site_code varchar(255), status varchar(255) not null, primary key (id));
create table proofs_of_delivery (delivered_litres numeric(38,2) not null, at timestamp(6) with time zone not null, delivery_id uuid not null unique, id uuid not null, notes varchar(500), signed_by varchar(255) not null, signature oid, primary key (id));
create table pump_events (reading_value numeric(38,2), at timestamp(6) with time zone not null, id uuid not null, kind varchar(255) not null, pump_id varchar(255) not null, site_code varchar(255) not null, primary key (id));
create table reconciliation_runs (business_date date not null, dispensed_litres numeric(38,2), exceptions integer not null, totalizer_litres numeric(38,2), at timestamp(6) with time zone not null, id uuid not null, summary varchar(600), site_code varchar(255) not null, status varchar(255) not null, primary key (id));
create table risk_events (score integer not null, created_at timestamp(6) with time zone not null, id uuid not null, ref_id uuid, details varchar(800) not null, attendant_name varchar(255), auto_action varchar(255) not null, driver_name varchar(255), organization varchar(255), ref_type varchar(255), rule varchar(255) not null, severity varchar(255) not null, site_code varchar(255), status varchar(255) not null, vehicle_reg varchar(255), primary key (id));
create table settlement_runs (fee numeric(38,2) not null, fee_percent numeric(38,2) not null, gross numeric(38,2) not null, net numeric(38,2) not null, at timestamp(6) with time zone not null, period_from timestamp(6) with time zone not null, period_to timestamp(6) with time zone not null, id uuid not null, status varchar(255) not null, supplier varchar(255) not null, primary key (id));
create table stock_movements (litres numeric(38,2) not null, at timestamp(6) with time zone not null, id uuid not null, ref_id uuid, kind varchar(255) not null, product varchar(255) not null, ref_type varchar(255), site_code varchar(255) not null, primary key (id));
create table tank_deliveries (documented_litres numeric(38,2) not null, measured_litres numeric(38,2) not null, variance_litres numeric(38,2) not null, at timestamp(6) with time zone not null, delivery_id uuid not null, id uuid not null, product varchar(255) not null, site_code varchar(255) not null, primary key (id));
create table tank_readings (tc_volume_litres numeric(38,2), temperaturec numeric(38,2), volume_litres numeric(38,2) not null, water_mm numeric(38,2), at timestamp(6) with time zone not null, received_at timestamp(6) with time zone not null, id uuid not null, product varchar(255) not null, site_code varchar(255) not null, primary key (id));
create table tanks (capacity_litres numeric(38,2) not null, opening_litres numeric(38,2) not null, reorder_litres numeric(38,2) not null, id uuid not null, product varchar(255) not null, site_code varchar(255) not null, primary key (id), unique (site_code, product));
create table tax_rates (rate_percent numeric(38,2) not null, valid_from date not null, id uuid not null, country varchar(255) not null, name varchar(255) not null, primary key (id));
create table variance_exceptions (actual_litres numeric(38,2), expected_litres numeric(38,2), variance_litres numeric(38,2), created_at timestamp(6) with time zone not null, id uuid not null, run_id uuid not null, note varchar(500), kind varchar(255) not null, product varchar(255), resolved_by varchar(255), site_code varchar(255) not null, status varchar(255) not null, primary key (id));
create table vehicles (active boolean not null, tank_capacity_litres numeric(38,2) not null, id uuid not null, description varchar(255), fuel_type varchar(255) not null, organization varchar(255) not null, registration varchar(255) not null, primary key (id), unique (organization, registration));
create index IDXtj7lpha6m35is73xmbwfwt8fq on gps_positions (delivery_id, at);
create index IDXce47kqspx62ykckuj31pgdgvk on pump_events (site_code, pump_id, at);
create index IDXlvskao0eqgd6inb4i6jrpqwqo on tank_readings (site_code, product, at);
